type LocaleContextValue = { locale: Locale; setLocale: (locale: Locale) => void; t: (text: string) => string };
const LocaleContext = createContext<LocaleContextValue>({ locale: "vi", setLocale: () => {}, t: (text) => text });
const translateText = (text: string, locale: Locale) => {
  if (locale !== "en") return text;
  const trimmed = text.trim();
  const translated = en[trimmed];
  let result = translated;
  if (result === undefined && trimmed.includes(" · ")) result = trimmed.split(" · ").map((part) => en[part] ?? part).join(" · ");
  if (result === undefined) {
    const page = trimmed.match(/^Trang (\d+)(?: \/ (\d+))?$/);
    const unread = trimmed.match(/^(\d+) chưa đọc$/);
    const campaignCount = trimmed.match(/^(\d+) chiến dịch$/);
    if (page) result = `Page ${page[1]}${page[2] ? ` / ${page[2]}` : ""}`;
    else if (unread) result = `${unread[1]} unread`;
    else if (campaignCount) result = `${campaignCount[1]} campaigns`;
  }
  if (result === undefined) return text;
  const start = text.match(/^\s*/)?.[0] ?? "";
  const end = text.match(/\s*$/)?.[0] ?? "";
  return `${start}${result}${end}`;
};

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>("vi");
  useEffect(() => {
    const saved = window.localStorage.getItem("giveaid-locale");
    if (saved === "en" || saved === "vi") setLocaleState(saved);
  }, []);
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const value = useMemo<LocaleContextValue>(() => ({
    locale,
    setLocale(next) { window.localStorage.setItem("giveaid-locale", next); setLocaleState(next); },
    t(text) { return translateText(text, locale); },
  }), [locale]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLocale() { return useContext(LocaleContext); }

function translateNode(node: ReactNode, locale: Locale): ReactNode {
  if (typeof node === "string") return translateText(node, locale);
  if (Array.isArray(node)) return Children.map(node, (child) => translateNode(child, locale));
  if (!isValidElement<Record<string, unknown>>(node)) return node;
  const props = node.props;
  const nextProps: Record<string, unknown> = {};
  if (locale === "en") {
    for (const key of ["aria-label", "aria-description", "placeholder", "title", "alt"]) {
      const value = props[key];
      if (typeof value === "string" && en[value.trim()]) nextProps[key] = translateText(value, locale);
    }
  }
  if (props.children === undefined) return Object.keys(nextProps).length ? cloneElement(node, nextProps) : node;
  return cloneElement(node, nextProps, translateNode(props.children as ReactNode, locale));
}

export function LocalizedTree({ children }: { children: ReactNode }) {
  const { locale } = useLocale();
  return <>{translateNode(children, locale)}</>;
}

export function LanguageSwitch() {
  const { locale, setLocale } = useLocale();
  return <div className="ga-language-switch" role="group" aria-label={locale === "vi" ? "Chọn ngôn ngữ" : "Choose language"}>
    <button type="button" className={locale === "vi" ? "is-active" : ""} aria-pressed={locale === "vi"} onClick={() => setLocale("vi")}>VI</button>
    <span aria-hidden="true">/</span>
    <button type="button" className={locale === "en" ? "is-active" : ""} aria-pressed={locale === "en"} onClick={() => setLocale("en")}>EN</button>
  </div>;
}
